27	/// Sidecar holding the cached packument's conditional-GET validators
28	/// (see [`CacheValidators`]). Lives next to [`PACKUMENT_FILE`] in the
29	/// disposable cache store only; hosted packuments have no upstream to
30	/// revalidate against. The leading dot keeps it out of the
31	/// package-listing walk and any static-serve view.
32	const PACKUMENT_META_FILE: &str = ".package.json.meta";
33	const TARBALL_INTEGRITY_SUFFIX: &str = ".integrity";
