35	/// Per-process counter feeding [`unique_tmp_path`] so two concurrent
36	/// writes to the same path don't collide on the same temp filename.
37	/// Combined with the pid and random suffix, the rename is still atomic
38	/// on POSIX as long as src and dest sit in the same directory (they do).
39	static TMP_COUNTER: AtomicU64 = AtomicU64::new(0);
40	const MAX_TEMP_CREATE_ATTEMPTS: usize = 16;
