/// hashes to `integrity` at end-of-stream. Every other outcome leaves the
/// cache untouched and removes the temp file through [`TarballWrite`]'s
/// [`Drop`]:
///
/// * a declared `Content-Length` over `max_bytes` fails synchronously with
///   [`TarballStreamError::TooLarge`] before streaming begins;
/// * an SRI mismatch still streams every (tampered) byte to the client but
///   abandons the temp file, so poisoned bytes never become cache-visible;
/// * an upstream transport error or truncation surfaces as an error on the
///   response body and abandons the temp file;
/// * dropping the body mid-stream (a client disconnect) drops the
///   [`TarballWrite`] and abandons it too.
pub fn stream_verified_to_cache(
