        // we hand control back, so an over-declared response leaves nothing
        // behind on disk.
        return Err(TarballStreamError::TooLarge { limit: max_bytes, received });
    }
    let checker = integrity_checker(integrity).map_err(TarballStreamError::Integrity)?;
    let state = TeeToCache {
        upstream: response.bytes_stream(),
        write,
        checker,
        written: 0,
        max_bytes,
    };
    // Carry the whole download through the unfold *state* so each poll owns
    // the temp writer: if the client drops the body mid-stream the state is
    // dropped with it, and `TarballWrite`'s `Drop` removes the temp file.
    let stream = stream::unfold(Some(state), |state| async move {
        let mut state = state?;
        match state.upstream.next().await {
            Some(Ok(chunk)) => {
                let received = state.written.saturating_add(chunk.len() as u64);
